// Plugin keys (signed-gateway ServerCredential) admin API — ROOT ONLY (routes/admin.routes.ts).
// Contract: backend/contracts/vip-2026-10.md §Plugin keys.
//
//   GET  /admin/plugin-keys                 list (never a secret; keyId + metadata only)
//   POST /admin/plugin-keys                 issue  { serverId, label? }        -> secret ONCE
//   POST /admin/plugin-keys/:id/rotate      rotate { label?, revokePrevious? } -> secret ONCE
//   POST /admin/plugin-keys/:id/revoke      revoke { reason }
//
// The plaintext secret is generated by pluginCredentialService, returned in exactly one response
// (Cache-Control: no-store) and stored only encrypted. It is never written to the audit log.
import { NextFunction, Response } from 'express';
import { z } from 'zod';
import prisma from '../config/database.js';
import { AuthRequest } from '../middlewares/auth.js';
import { AppError } from '../middlewares/errorHandler.js';
import auditService from '../services/audit.service.js';
import pluginCredentialService from '../services/pluginCredential.service.js';
import { paginateQuery, parsePagination, parseSearch } from '../utils/pagination.js';

export const PLUGIN_KEY_STATUSES = ['active', 'revoked'] as const;

const labelSchema = z.string().trim().min(1).max(120);
export const issuePluginKeySchema = z.object({ serverId: z.number().int().positive(), label: labelSchema.optional() }).strict();
export const rotatePluginKeySchema = z.object({ label: labelSchema.optional(), revokePrevious: z.boolean().optional() }).strict();
export const revokePluginKeySchema = z.object({ reason: z.string().trim().min(3).max(500) }).strict();

function parse<T extends z.ZodTypeAny>(schema: T, body: unknown, label: string): z.infer<T> {
  const parsed = schema.safeParse(body ?? {});
  if (!parsed.success) {
    throw new AppError(`Invalid ${label}: ${parsed.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ')}`, 400);
  }
  return parsed.data;
}

const KEY_SELECT = {
  id: true,
  serverId: true,
  keyId: true,
  label: true,
  status: true,
  createdAt: true,
  rotatedAt: true,
  revokedAt: true,
  lastUsedAt: true,
  server: { select: { id: true, name: true, map: true, isActive: true, drainMode: true, lastHeartbeat: true } },
} as const;

/** Public projection: there is no secret column in KEY_SELECT, so none can leak from here. */
export function toPluginKey(row: any) {
  const iso = (value: Date | null | undefined) => (value instanceof Date ? value.toISOString() : value ?? null);
  return {
    id: row.id,
    serverId: row.serverId,
    server: row.server
      ? {
          id: row.server.id,
          name: row.server.name,
          map: row.server.map ?? null,
          isActive: row.server.isActive,
          drainMode: row.server.drainMode,
          lastHeartbeat: iso(row.server.lastHeartbeat),
        }
      : null,
    keyId: row.keyId,
    label: row.label ?? null,
    status: row.status,
    createdAt: iso(row.createdAt),
    rotatedAt: iso(row.rotatedAt),
    revokedAt: iso(row.revokedAt),
    lastUsedAt: iso(row.lastUsedAt),
  };
}

function noStore(res: Response) {
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Pragma', 'no-cache');
}

export class AdminPluginKeysController {
  // GET /admin/plugin-keys?page&pageSize&serverId&status&search
  list = async (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      const query = (req.query ?? {}) as Record<string, unknown>;
      const and: any[] = [];
      const rawServer = typeof query.serverId === 'string' ? query.serverId.trim() : undefined;
      if (rawServer && rawServer.toLowerCase() !== 'all') {
        if (!/^\d{1,9}$/.test(rawServer) || Number(rawServer) <= 0) throw new AppError('Invalid serverId', 400);
        and.push({ serverId: Number(rawServer) });
      }
      const rawStatus = typeof query.status === 'string' ? query.status.trim().toLowerCase() : undefined;
      if (rawStatus && rawStatus !== 'all') {
        if (!(PLUGIN_KEY_STATUSES as readonly string[]).includes(rawStatus)) {
          throw new AppError(`Invalid status: expected one of ${PLUGIN_KEY_STATUSES.join(', ')}`, 400);
        }
        and.push({ status: rawStatus });
      }
      const search = parseSearch(query.search);
      if (search) {
        and.push({
          OR: [
            { keyId: { startsWith: search } },
            { label: { contains: search, mode: 'insensitive' } },
            { server: { name: { contains: search, mode: 'insensitive' } } },
          ],
        });
      }
      const where = and.length > 0 ? { AND: and } : {};
      const { result, pagination } = await paginateQuery(parsePagination(query), (skip, take) =>
        prisma.$transaction([
          prisma.serverCredential.count({ where }),
          prisma.serverCredential.findMany({
            where,
            select: KEY_SELECT,
            orderBy: [{ status: 'asc' }, { createdAt: 'desc' }, { id: 'asc' }],
            skip,
            take,
          }),
        ]) as Promise<[number, any[]]>,
      );
      res.json({ items: result[1].map(toPluginKey), pagination });
    } catch (error) {
      next(error);
    }
  };

  // POST /admin/plugin-keys { serverId, label? } -> 201 { key, secret } (secret shown once)
  issue = async (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      const body = parse(issuePluginKeySchema, req.body, 'plugin key');
      const label = body.label ?? `admin:${req.user!.id}:${new Date().toISOString()}`;
      const issued = await pluginCredentialService.issue(body.serverId, label);
      const row = await prisma.serverCredential.findUnique({ where: { id: issued.id }, select: KEY_SELECT });
      await auditService.log({
        userId: req.user!.id,
        action: 'plugin_key_issue',
        resource: 'server_credential',
        resourceId: issued.id,
        newValue: { serverId: issued.serverId, keyId: issued.keyId, label },
      }, req);
      noStore(res);
      res.status(201).json({
        key: row ? toPluginKey(row) : { id: issued.id, serverId: issued.serverId, keyId: issued.keyId, label, status: 'active' },
        secret: issued.secret,
        secretShownOnce: true,
      });
    } catch (error) {
      next(error);
    }
  };

  // POST /admin/plugin-keys/:id/rotate { label?, revokePrevious? } -> 201 { key, secret, previous }
  // Issues a NEW pair for the same server. The old key stays active (zero-downtime overlap) unless
  // revokePrevious is true; revoke it later with /revoke once the plugin uses the new keyId.
  rotate = async (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      const body = parse(rotatePluginKeySchema, req.body, 'rotation');
      const existing = await prisma.serverCredential.findUnique({ where: { id: req.params.id }, select: KEY_SELECT });
      if (!existing) throw new AppError('Plugin key not found', 404);
      if (existing.status !== 'active') throw new AppError('Only an active key can be rotated; issue a new key instead', 409);
      const label = body.label ?? `rotated-from:${existing.keyId}`;
      const issued = await pluginCredentialService.rotate(existing.serverId, body.revokePrevious ? existing.keyId : undefined, label);
      await prisma.serverCredential.update({ where: { id: existing.id }, data: { rotatedAt: new Date() } });
      const [row, previous] = await Promise.all([
        prisma.serverCredential.findUnique({ where: { id: issued.id }, select: KEY_SELECT }),
        prisma.serverCredential.findUnique({ where: { id: existing.id }, select: KEY_SELECT }),
      ]);
      await auditService.log({
        userId: req.user!.id,
        action: 'plugin_key_rotate',
        resource: 'server_credential',
        resourceId: existing.id,
        oldValue: { keyId: existing.keyId, status: existing.status },
        newValue: { newCredentialId: issued.id, newKeyId: issued.keyId, serverId: issued.serverId, previousRevoked: Boolean(body.revokePrevious), label },
      }, req);
      noStore(res);
      res.status(201).json({
        key: row ? toPluginKey(row) : { id: issued.id, serverId: issued.serverId, keyId: issued.keyId, label, status: 'active' },
        secret: issued.secret,
        secretShownOnce: true,
        previous: previous ? toPluginKey(previous) : null,
      });
    } catch (error) {
      next(error);
    }
  };

  // POST /admin/plugin-keys/:id/revoke { reason } -> { key }
  revoke = async (req: AuthRequest, res: Response, next: NextFunction) => {
    try {
      const body = parse(revokePluginKeySchema, req.body, 'revocation');
      const existing = await prisma.serverCredential.findUnique({ where: { id: req.params.id }, select: KEY_SELECT });
      if (!existing) throw new AppError('Plugin key not found', 404);
      if (existing.status === 'revoked') {
        res.json({ key: toPluginKey(existing), alreadyRevoked: true });
        return;
      }
      await pluginCredentialService.revoke(existing.keyId);
      const row = await prisma.serverCredential.findUnique({ where: { id: existing.id }, select: KEY_SELECT });
      await auditService.log({
        userId: req.user!.id,
        action: 'plugin_key_revoke',
        resource: 'server_credential',
        resourceId: existing.id,
        oldValue: { status: existing.status },
        newValue: { status: 'revoked', keyId: existing.keyId, serverId: existing.serverId, reason: body.reason },
      }, req);
      res.json({ key: toPluginKey(row ?? { ...existing, status: 'revoked' }) });
    } catch (error) {
      next(error);
    }
  };
}

export const adminPluginKeysController = new AdminPluginKeysController();
export default adminPluginKeysController;
